        TRefused(0, emon.Testport.TextBlob("asset-dpi=12x"), "asset-dpi wants a number, not \"12x\"");
        TRefused(0, emon.Testport.TextBlob("max-rounds=99999999999"), "max-rounds wants a number, not \"99999999999\"");
        TRefused(0, emon.Testport.TextBlob("limit.pages=lots"), "limit.pages wants a number, not \"lots\"");
        TRefused(0, emon.Testport.TextBlob("chunk=0"), "chunk is out of range 1..2147483647");
        TRefused(0, emon.Testport.TextBlob("parallel=0"), "parallel is out of range 1..2147483647");
        TRefused(0, emon.Testport.TextBlob("parallel=many"), "parallel wants a number, not \"many\"");
        TRefused(0, emon.Testport.TextBlob("limit.pages=-1"), "limit.pages is out of range 0..2147483647");
        TRefused(0, emon.Testport.TextBlob("limit.form-depth=33"), "limit.form-depth is out of range 0..32");
    }
    [Xunit.Fact]
    public static void TestAnUnknownKeyOrALineWithoutAValueIsRefusedByName() {
        TRefused(0, emon.Testport.TextBlob("bogus=1"), "unknown option bogus");
        TRefused(0, emon.Testport.TextBlob("ocr=auto\nbogus=1"), "unknown option bogus");
        TRefused(0, emon.Testport.TextBlob("limit.nope=5"), "no limit named nope");
        TRefused(0, emon.Testport.TextBlob("limit.=5"), "no limit named ");
        TRefused(0, emon.Testport.TextBlob("novalue"), "option \"novalue\" has no value");
        TRefused(0, emon.Testport.TextBlob("ocr=auto\nnovalue"), "option \"novalue\" has no value");
    }
    [Xunit.Fact]
    public static void TestALimitIsFoundByItsName() {
        emon.Port.Cells t = emon.Port.NewCells();
        TCps(t, emon.Testport.TextBlob("ref-depth"));
        emon.Testport.AssertEq(Config.CfLimitFind(t, 0, 9), 4, "ref-depth");
        emon.Testport.AssertEq(Config.CfLimitFind(t, 0, 8), -1, "a prefix of it");
        emon.Testport.AssertEq(Config.CfLimitFind(t, 4, 9), -1, "its tail");
        emon.Testport.AssertEq(Config.CfKeyFind(t, 0, 9), -1, "not a key");
    }
    [Xunit.Fact]
    public static void TestTheLimitsOfP104AreFoundByTheirNames() {
        emon.Port.Cells t = emon.Port.NewCells();
        TCps(t, emon.Testport.TextBlob("asset-placements"));
        emon.Testport.AssertEq(Config.CfLimitFind(t, 0, 16), 13, "asset-placements");
        emon.Port.CellsDrop(t, 0);
        TCps(t, emon.Testport.TextBlob("ocr-requests"));
        emon.Testport.AssertEq(Config.CfLimitFind(t, 0, 12), 10, "ocr-requests");
        emon.Port.CellsDrop(t, 0);
        TCps(t, emon.Testport.TextBlob("note-refs"));
        emon.Testport.AssertEq(Config.CfLimitFind(t, 0, 9), 12, "note-refs");
        emon.Port.CellsDrop(t, 0);
        TCps(t, emon.Testport.TextBlob("fonts-per-doc"));
        emon.Testport.AssertEq(Config.CfLimitFind(t, 0, 13), 14, "fonts-per-doc");
        emon.Port.CellsDrop(t, 0);
        TCps(t, emon.Testport.TextBlob("stage-ms"));
        emon.Testport.AssertEq(Config.CfLimitFind(t, 0, 8), 15, "stage-ms");
        emon.Port.CellsDrop(t, 0);
        TCps(t, emon.Testport.TextBlob("workers"));
        emon.Testport.AssertEq(Config.CfLimitFind(t, 0, 7), 16, "workers");
    }
